#include <string>
#include <vector>
#include <sstream>
using namespace std;

class Solution {
public:
    string reorderSpaces(string text) {
        int total_spaces = 0;
        for (char c : text) {
            if (c == ' ') total_spaces++;
        }
        stringstream ss(text);
        string word;
        vector<string> words;
        while (ss >> word) {
            words.push_back(word);
        }
        int n = words.size();
        if (n == 1) {
            return words[0] + string(total_spaces, ' ');
        }
        int gap = total_spaces / (n - 1);
        int rem = total_spaces % (n - 1);
        string res = "";
        for (int i = 0; i < n; ++i) {
            res += words[i];
            if (i < n - 1) res += string(gap, ' ');
        }
        res += string(rem, ' ');
        return res;
    }
};

import java.util.*;

class Solution {
    public String reorderSpaces(String text) {
        int totalSpaces = 0;
        for (int i = 0; i < text.length(); ++i) {
            if (text.charAt(i) == ' ') totalSpaces++;
        }
        String[] words = text.trim().split("\\s+");
        int n = words.length;
        if (n == 1) {
            return words[0] + " ".repeat(totalSpaces);
        }
        int gap = totalSpaces / (n - 1);
        int rem = totalSpaces % (n - 1);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; ++i) {
            sb.append(words[i]);
            if (i < n - 1) sb.append(" ".repeat(gap));
        }
        sb.append(" ".repeat(rem));
        return sb.toString();
    }
}

/**
 * @param {string} text
 * @return {string}
 */
var reorderSpaces = function(text) {
    let totalSpaces = 0;
    for (const c of text) {
        if (c === ' ') totalSpaces++;
    }
    const words = text.trim().split(/\s+/);
    const n = words.length;
    if (n === 1) {
        return words[0] + ' '.repeat(totalSpaces);
    }
    const gap = Math.floor(totalSpaces / (n - 1));
    const rem = totalSpaces % (n - 1);
    return words.join(' '.repeat(gap)) + ' '.repeat(rem);
};
